# ==============================================================================# 021_SECURITY_ENGINE.py# ==============================================================================import sqlite3import hashlibimport secretsfrom pathlib import Pathfrom datetime import datetimeROOT = Path(__file__).resolve().parentDB = ROOT / "MISSION_CONTROL" / "database" / "mission_control.db"conn = sqlite3.connect(DB, timeout=30)conn.row_factory = sqlite3.Rowcur = conn.cursor()

cur.execute("PRAGMA journal_mode=WAL")
cur.execute("PRAGMA synchronous=NORMAL")
cur.execute("PRAGMA busy_timeout=30000")cur.execute("""CREATE TABLE IF NOT EXISTS users(    id INTEGER PRIMARY KEY AUTOINCREMENT,    created_at TEXT,    username TEXT UNIQUE,    password_hash TEXT,    api_key TEXT,    role TEXT,    status TEXT)""")conn.commit()def create_user(username,password,role="ADMIN"):    password_hash = hashlib.sha256(        password.encode()    ).hexdigest()    api_key = secrets.token_hex(32)    cur.execute(        """        INSERT OR IGNORE INTO users(            created_at,            username,            password_hash,            api_key,            role,            status        )        VALUES(?,?,?,?,?,?)        """,        (            datetime.now().isoformat(),            username,            password_hash,            api_key,            role,            "ACTIVE"        )    )    conn.commit()create_user(    "admin",    "iotec123")cur.execute("""SELECTid,username,role,statusFROM users""")print("="*80)print("SECURITY ENGINE")print("="*80)for row in cur.fetchall():    print(dict(row))print("="*80)conn.close()

